{"query":"query ContentFactoryRadarCatalog($firstPosts: Int!, $firstTerms: Int!) {
  posts(first: $firstPosts, where: { stati: [PUBLISH] }) {
    nodes {
      id
      databaseId
      title
      slug
      status
      excerpt
      date
      modified
      link
      categories { nodes { id databaseId name slug } }
      tags { nodes { id databaseId name slug } }
    }
  }
  categories(first: $firstTerms) { nodes { id databaseId name slug } }
  tags(first: $firstTerms) { nodes { id databaseId name slug } }
}","variables":{"firstPosts":50,"firstTerms":100}}

parameters.jsCode:
const base = $('Guard — Radar fail closed').first().json;
const transportPayload = $input.first().json ?? {};
const payload = transportPayload?.body && typeof transportPayload.body === 'object'
  ? transportPayload.body
  : transportPayload;

const cleanText = (value) => String(value ?? '')
  .replace(/<[^>]*>/gu, ' ')
  .replace(/&hellip;|&#8230;/gu, '…')
  .replace(/&amp;/gu, '&')
  .replace(/\s+/gu, ' ')
  .trim();

const nodesAt = (value) => Array.isArray(value?.nodes) ? value.nodes : [];
const graphqlErrors = Array.isArray(payload?.errors) ? payload.errors : [];
const responseKeys = Object.keys(transportPayload);
const compressedStreamResponse = [
  '_writeState',
  '_readableState',
  '_writableState',
  '_handle',
].some((key) => responseKeys.includes(key));

const transportError = Boolean(
  compressedStreamResponse
  || transportPayload?.error
  || (
    !payload?.data
    && typeof transportPayload?.message === 'string'
    && transportPayload.message.trim()
  )
);

const rawPosts = nodesAt(payload?.data?.posts);
const rawCategories = nodesAt(payload?.data?.categories);
const rawTags = nodesAt(payload?.data?.tags);

const posts = rawPosts.map((row) => ({
  post_id: Number(row.databaseId),
  title: cleanText(row.title),
  slug: String(row.slug ?? '').trim(),
  url: row.slug
    ? 'https://site.example.invalid/blog/' + String(row.slug).replace(/^\/+|\/+$/gu, '') + '/'
    : '',
  excerpt: cleanText(row.excerpt),
  categories: nodesAt(row.categories).map((item) => ({
    category_id: Number(item.databaseId),
    name: cleanText(item.name),
    slug: String(item.slug ?? ''),
  })).filter((item) => Number.isInteger(item.category_id) && item.category_id > 0),
  tags: nodesAt(row.tags).map((item) => ({
    tag_id: Number(item.databaseId),
    name: cleanText(item.name),
    slug: String(item.slug ?? ''),
  })).filter((item) => Number.isInteger(item.tag_id) && item.tag_id > 0),
  published_at: row.date ?? null,
  updated_at: row.modified ?? null,
})).filter((row) =>
  Number.isInteger(row.post_id)
  && row.post_id > 0
  && row.title
  && row.slug
  && row.url
);

const categories = rawCategories.map((row) => ({
  category_id: Number(row.databaseId),
  name: cleanText(row.name),
  slug: String(row.slug ?? ''),
})).filter((row) =>
  Number.isInteger(row.category_id)
  && row.category_id > 0
  && row.name
  && row.slug
);

const tags = rawTags.map((row) => ({
  tag_id: Number(row.databaseId),
  name: cleanText(row.name),
  slug: String(row.slug ?? ''),
})).filter((row) =>
  Number.isInteger(row.tag_id)
  && row.tag_id > 0
  && row.name
  && row.slug
);

const passed = (
  !transportError
  && graphqlErrors.length === 0
  && posts.length > 0
  && categories.length > 0
  && tags.length > 0
);

const warnings = [...base.warnings];

