const completedWebSearchItems = webSearchItems.filter((item) => item?.status === 'completed');
const unprocessedWebSearchItems = webSearchItems.filter((item) => item?.status !== 'completed');
const unprocessedWebSearchItemsSafe = unprocessedWebSearchItems.every((item) =>
  ['searching', 'in_progress', 'incomplete'].includes(item?.status)
);
const webSearchCalls = completedWebSearchItems.length;
const webSearchCallValid = webSearchCalls === Number(request.configuration.MAX_WEB_SEARCH_CALLS ?? 0)
  && unprocessedWebSearchItemsSafe;
const actualCost = payload
  ? tokenCost + webSearchCalls * Number(pricing.OPENAI_WEB_SEARCH_USD_PER_CALL ?? 0)
  : null;
const rawCode = String(error?.code ?? error?.type ?? raw?.code ?? '').toLowerCase();
const creditExhausted = rawCode === 'credit_balance_exhausted';
const circuitOpen = request.provider_circuit?.state === 'OPEN' || rawCode === 'provider_circuit_open';
const technicalCode = creditExhausted ? 'CREDIT_BALANCE_EXHAUSTED' : circuitOpen ? (request.provider_circuit?.technical_code || 'PROVIDER_CIRCUIT_OPEN') : error ? 'OPENAI_TRANSPORT_ERROR' : parseError ? 'OPENAI_RESPONSE_PARSE_ERROR' : null;
const sanitized_error = technicalCode ? { schema_version: '1.1.0', provider: 'openai', stage: 'TOPIC_RADAR', http_status: statusCode, technical_code: technicalCode, human_message: creditExhausted ? 'O saldo de créditos do provider de IA está indisponível para este ciclo.' : circuitOpen ? 'O provider de IA permanece temporariamente indisponível; novas chamadas foram bloqueadas.' : 'O provider de IA não respondeu de forma utilizável para este ciclo.', recommended_action: creditExhausted ? 'Regularizar o saldo ou a cobrança da conta OpenAI antes de liberar um novo ciclo.' : 'Investigar a indisponibilidade do provider antes de uma nova execução.', retryable: !creditExhausted && !circuitOpen && [429,500,502,503,504].includes(statusCode), circuit_breaker: { provider: 'openai', state: (creditExhausted || circuitOpen || [429,500,502,503,504].includes(statusCode)) ? 'OPEN' : 'CLOSED', technical_code: technicalCode } } : null;
if (sanitized_error?.circuit_breaker?.state === 'OPEN') { const staticData = $getWorkflowStaticData('global'); staticData.meta14_openai_circuit = { provider: 'openai', state: 'OPEN', technical_code: sanitized_error.technical_code, http_status: sanitized_error.http_status, retryable: sanitized_error.retryable, human_message: sanitized_error.human_message, recommended_action: sanitized_error.recommended_action, marked_at: new Date().toISOString(), source: 'PROVIDER_RESPONSE' }; }
const valid = Boolean(
  !error
  && !parseError
  && payload
  && webSearchCallValid
  && (!statusCode || (statusCode >= 200 && statusCode < 300))
);

return [{ json: {
  ...(valid ? payload : {}),
  sanitized_error, provider_circuit: sanitized_error?.circuit_breaker ?? request.provider_circuit ?? { provider: 'openai', state: 'CLOSED' },
  radar_transport: {
    valid,
    status_code: statusCode,
    error_code: technicalCode ?? (!webSearchCallValid ? (webSearchCalls > Number(request.configuration.MAX_WEB_SEARCH_CALLS ?? 0) ? 'OPENAI_WEB_SEARCH_CALL_LIMIT_EXCEEDED' : 'OPENAI_WEB_SEARCH_CALL_REQUIRED') : null),
    retry_performed: false,
    response_body_persisted: false,
    observed_web_search_items: webSearchItems.length,
