    unprocessed_web_search_sources_ignored: unprocessedWebSearchItemsSafe ? unprocessedWebSearchItems.reduce((total, item) => total + (Array.isArray(item?.action?.sources) ? item.action.sources.length : 0), 0) : 0,
  },
  radar_usage: {
    ...request.radar_usage,
    ai_calls_used: circuitOpen ? 0 : 1,
    web_search_calls_used: webSearchCalls,
    input_tokens: inputTokens,
    cached_input_tokens: cachedTokens,
    output_tokens: outputTokens,
    estimated_cost_usd: circuitOpen ? 0 : request.configuration.estimated_radar_cost_usd,
    actual_cost_usd: actualCost === null ? null : Number(actualCost.toFixed(6)),
    currency: 'USD',
