const prepared = $('Fontes — Preparar verificação pública').all()
  .map((item) => item.json ?? {})
  .filter((item) => item.skip_public_source_read !== true && item.source_verification_request);
const responses = $input.all().map((item) => item.json ?? {});
const MAX_REDIRECTS_PER_EXECUTION = Number($('Entrada — Normalizar radar').first().json?.configuration?.MAX_REDIRECTS_PER_EXECUTION ?? 18);

function headerValue(headers, name) {
  if (!headers || typeof headers !== 'object') return '';
  const entry = Object.entries(headers).find(([key]) => String(key).toLowerCase() === name);
  const value = entry?.[1];
  return Array.isArray(value) ? String(value[0] ?? '').trim() : String(value ?? '').trim();
}

function privateHost(hostname) {
  const host = String(hostname ?? '').toLowerCase().replace(/^\[|\]$/gu, '');
  if (!host) return true;
  if (host === 'localhost' || ['.localhost', '.local', '.internal', '.lan', '.home', '.corp', '.invalid'].some((suffix) => host.endsWith(suffix))) return true;
  if (host.includes(':')) return host === '::' || host === '::1' || host.startsWith('fc') || host.startsWith('fd') || /^fe[89ab]/u.test(host) || host.includes('::ffff:');
  if (!/^\d+\.\d+\.\d+\.\d+$/u.test(host)) return false;
  const octets = host.split('.').map(Number);
  if (octets.length !== 4 || octets.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) return true;
  const [a, b] = octets;
  return a === 0 || a === 10 || a === 127 || a >= 224
    || (a === 100 && b >= 64 && b <= 127) || (a === 169 && b === 254)
    || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168)
    || (a === 198 && (b === 18 || b === 19));
}

function comparableHost(hostname) {
  const host = String(hostname ?? '').toLowerCase().replace(/^www\./u, '');
  const labels = host.split('.').filter(Boolean);
  if (labels.length <= 2) return host;
  const suffix2 = labels.slice(-2).join('.');
  const multipart = new Set(['com.br','org.br','gov.br','edu.br','net.br','co.uk','org.uk','gov.uk','com.au','org.au']);
  return multipart.has(suffix2) && labels.length >= 3 ? labels.slice(-3).join('.') : suffix2;
}

function parseHttpsUrl(value) {
  const raw = String(value ?? '').trim().split('#')[0];
  if (!raw || raw.length > 2048 || /[\u0000-\u001f\u007f\\]/u.test(raw)) return null;
  const match = /^https:\/\/([^/?#]+)([^#]*)$/iu.exec(raw);
  if (!match || match[1].includes('@')) return null;
  const authority = match[1].toLowerCase();
  let hostname = authority;
  let port = '';
  if (authority.startsWith('[')) {
    const closing = authority.indexOf(']');
    if (closing < 0) return null;
    hostname = authority.slice(1, closing);
    const suffix = authority.slice(closing + 1);
    if (suffix && suffix !== ':443') return null;
    port = suffix ? '443' : '';
  } else {
    const portMatch = /^(.*):(\d+)$/u.exec(authority);
    if (portMatch) {
      hostname = portMatch[1];
      port = portMatch[2];
      if (port !== '443') return null;
    }
  }
  if (!hostname) return null;
  const normalizedAuthority = hostname.includes(':') ? '[' + hostname + ']' : hostname;
  const suffix = match[2] || '/';
  return { hostname, origin: 'https://' + normalizedAuthority, url: 'https://' + normalizedAuthority + suffix };
}

function safeRedirect(originalUrl, location) {
  const rawLocation = String(location ?? '').trim();
  if (!rawLocation || rawLocation.length > 2048 || /[\u0000-\u001f\u007f\\]/u.test(rawLocation)) return { url: null, reason_code: 'SOURCE_REDIRECT_LOCATION_INVALID' };
  const original = parseHttpsUrl(originalUrl);
  if (!original) return { url: null, reason_code: 'SOURCE_REDIRECT_LOCATION_INVALID' };
  const absoluteTarget = /^https:\/\//iu.test(rawLocation)
    ? rawLocation
    : /^\/\//u.test(rawLocation)
      ? 'https:' + rawLocation
      : /^\/(?!\/)/u.test(rawLocation)
        ? original.origin + rawLocation
        : '';
  const target = parseHttpsUrl(absoluteTarget);
  if (!target) return { url: null, reason_code: 'SOURCE_REDIRECT_LOCATION_INVALID' };
  if (privateHost(target.hostname) || comparableHost(target.hostname) !== comparableHost(original.hostname)) {
    return { url: null, reason_code: 'SOURCE_REDIRECT_DESTINATION_BLOCKED' };
  }
  return { url: target.url, reason_code: null };
}

const directResponses = [];
const redirectRequests = [];
let redirectsRejected = 0;
for (let index = 0; index < prepared.length; index += 1) {
  const request = prepared[index].source_verification_request;
  const response = responses[index] ?? {};
  const statusCode = Number(response.statusCode ?? response.status ?? 0);
  const location = headerValue(response.headers, 'location');
  const redirectStatus = [301, 302, 303, 307, 308].includes(statusCode);
  if (!redirectStatus || !location) {
    directResponses.push({ ...response, _source_verification_request: request });
    continue;
  }
  const resolution = safeRedirect(request.url, location);
  if (!resolution.url || redirectRequests.length >= MAX_REDIRECTS_PER_EXECUTION) {
    redirectsRejected += 1;
    directResponses.push({
      ...response,
      _source_verification_request: request,
      _source_redirect: {
        followed: false,
        reason_code: resolution.reason_code || 'SOURCE_REDIRECT_LIMIT_EXCEEDED',
      },
    });
    continue;
  }
  redirectRequests.push({
    url: resolution.url,
    original_request: request,
    original_status_code: statusCode,
    redirect_hop: 1,
  });
}

return [{
  json: {
    direct_source_responses: directResponses,
    redirect_requests: redirectRequests,
    redirect_summary: {
      redirect_limit: MAX_REDIRECTS_PER_EXECUTION,
      redirects_planned: redirectRequests.length,
      redirects_rejected: redirectsRejected,
      retry_count: 0,
    },
  },
}];

const envelope = $input.first()?.json ?? {};
const requests = Array.isArray(envelope.redirect_requests) ? envelope.redirect_requests : [];
return requests.map((redirect_request) => ({ json: { redirect_request } }));

const plan = $('Fontes — Planejar redirects seguros').first()?.json ?? {};
const redirectItems = $('Fontes — Expandir redirects seguros').all().map((item) => item.json ?? {});
const redirectResponses = $input.all().map((item) => item.json ?? {});
const finalResponses = [...(Array.isArray(plan.direct_source_responses) ? plan.direct_source_responses : [])];
for (let index = 0; index < redirectItems.length; index += 1) {
  const redirectRequest = redirectItems[index].redirect_request ?? {};
  finalResponses.push({
    ...(redirectResponses[index] ?? {}),
    _source_verification_request: redirectRequest.original_request,
    _source_redirect: {
      followed: true,
      redirect_hop: 1,
      original_status_code: redirectRequest.original_status_code ?? null,
      final_url: redirectRequest.url ?? null,
      reason_code: null,
    },
  });
}
return [{
  json: {
    source_responses: finalResponses,
    redirect_summary: {
      ...(plan.redirect_summary ?? {}),
      redirects_followed: redirectItems.length,
      retry_count: 0,
    },
  },
}];
